// Original inspection order replay; native image outputs are never observer inputs.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.awt.geom.*;
public class StemImageHeadItemsProbe extends StemImageHeadChunksProbe {
 private final Object book;public StemImageHeadItemsProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static String link(Object l)throws Exception{String kind=l.getClass().getSimpleName();Object g=call(l,"getStump");String extra;if(kind.equals("CLinker")){Object sl=get(l,"this$1"),hl=get(sl,"this$0"),h=get(hl,"head");extra="\"kind\":\"HeadCorner\",\"head_bounds\":"+rect(call(h,"getBounds"))+",\"shape\":\""+call(h,"getShape")+"\",\"side\":\""+get(sl,"hSide")+"\",\"vertical\":\""+get(l,"vSide")+"\",\"beam_height\":null";}else{Object bl=get(l,"this$0"),b=get(bl,"beam");extra="\"kind\":\"Beam\",\"beam_median\":"+line(call(b,"getMedian"))+",\"beam_height\":"+call(b,"getHeight");}return "{"+extra+",\"reference\":"+point(call(l,"getReferencePoint"))+",\"stump\":"+(g==null?"null":physical(g))+"}";}
 static String items(List<?> is,Map<Object,Integer> ids)throws Exception{List<String>r=new ArrayList<>();for(Object it:is){Object g=get(it,"glyph"),l=null;if(it.getClass().getSimpleName().contains("LinkerItem"))l=get(it,"linker");r.add("{\"kind\":\""+it.getClass().getSimpleName()+"\",\"contrib\":"+get(it,"contrib")+",\"line\":"+line(get(it,"line"))+",\"glyph\":"+(g==null?"null":physical(g))+",\"linker_index\":"+(l==null?"null":ids.get(l))+"}");}return "["+String.join(",",r)+"]";}
 static String sections(Collection<?> all)throws Exception{List<String> out=new ArrayList<>();for(Object x:all){List<String> rs=new ArrayList<>();for(Object r:(List<?>)call(x,"getRuns"))rs.add("["+call(r,"getStart")+","+call(r,"getLength")+"]");out.add("{\"vertical\":"+call(x,"isVertical")+",\"first_pos\":"+call(x,"getFirstPos")+",\"bounds\":"+rect(call(x,"getBounds"))+",\"runs\":["+String.join(",",rs)+"]}");}return "["+String.join(",",out)+"]";}

 static String finalItems(Collection<?> all)throws Exception{List<String>out=new ArrayList<>();for(Object it:all){String kind=it.getClass().getSimpleName(),head="null",ref="null";Object g=get(it,"glyph");if(kind.contains("LinkerItem")){Object l=get(it,"linker");if(l.getClass().getSimpleName().equals("CLinker"))head=rect(call(call(l,"getSource"),"getBounds"));if(kind.equals("HalfLinkerItem"))ref=point(call(l,"getReferencePoint"));}out.add("{\"kind\":\""+kind+"\",\"gap\":"+kind.equals("GapItem")+",\"contrib\":"+get(it,"contrib")+",\"line\":"+line(get(it,"line"))+",\"line_bounds\":"+rect(((Line2D)get(it,"line")).getBounds())+",\"head_bounds\":"+head+",\"reference\":"+ref+",\"glyph\":"+(g==null?"null":physical(g))+"}");}return "["+String.join(",",out)+"]";}
 static String intMap(Map<?,?>m){List<String>r=new ArrayList<>();for(var e:m.entrySet())r.add("\""+e.getKey()+"\":"+e.getValue());return "{"+String.join(",",r)+"}";}
 static String prefixLengths(Object sb,int size)throws Exception{List<String>r=new ArrayList<>();for(int i=-1;i<size;i++)r.add(""+call(sb,"getLengthAt",i));return "["+String.join(",",r)+"]";}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");List<String>ss=new ArrayList<>();int count=0,total=0,kept=0,seedsCount=0;
 for(Object sys:(List<?>)call(sheet,"getSystems")){Object retr=inspect(sys,sheet),p=get(retr,"params");
 // Reconstruct legitimate original linkers, then repeat inspect order. This captures
 // each head's chosen BLinkers at its inspection time, before later anchors exist.
 for(Object b:(List<?>)get(retr,"systemBeams"))call(b,"setLinker",fresh(b,retr));
 for(Object h:(List<?>)get(retr,"systemHeads"))call(h,"setLinker",Class.forName("org.audiveris.omr.sheet.stem.HeadLinker").getConstructor(Class.forName("org.audiveris.omr.sig.inter.HeadInter"),Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever")).newInstance(h,retr));
 for(Object b:(List<?>)get(retr,"systemBeams"))call(call(b,"getLinker"),"inspectVLinkers");
 List<String>cs=new ArrayList<>();for(Object h:(List<?>)get(retr,"systemHeads")){Object hl=call(h,"getLinker");for(Object hc:(Object[])Class.forName("org.audiveris.omr.sheet.stem.HeadCorner").getMethod("values").invoke(null)){Object side=get(hc,"hSide"),vert=get(hc,"vSide"),c=call(hl,"getCornerLinker",side,vert),target=get(c,"targetBeam");List<Object>parts=new ArrayList<>((Collection<?>)call(c,"retrieveSeeds")),ls=new ArrayList<>((Collection<?>)call(c,"lookupOtherHeads"));boolean veto=call(h,"getShape").toString().equals("NOTEHEAD_VOID")&&(Integer)get(c,"yDir")== (Integer)call(side,"direction");
 if(target!=null&&!veto){Object hit=callStatic("math.LineUtil","intersection",call(target,"getMedian"),get(c,"theoLine"));for(Object b:(List<?>)call(call(target,"getLinker"),"getSiblingBeamsAt",hit))ls.add(call(call(b,"getLinker"),"findLinker",get(c,"theoLine")));}
 String input=glyphs(parts);List<String>lr=new ArrayList<>();Map<Object,Integer>ids=new IdentityHashMap<>();for(int i=0;i<ls.size();i++){lr.add(link(ls.get(i)));ids.put(ls.get(i),i+1);}total+=ls.size();seedsCount+=parts.size();
 call(c,"inspect",call(call(sheet,"getStub"),"getProfile"));Object sb=get(c,"sb"),stump=call(c,"getStump"),box=stump==null?null:call(stump,"getBounds");List<?>filtered=(List<?>)call(sb,"filter",box,parts,ls);List<Integer>indices=new ArrayList<>();for(Object l:ls)indices.add(ids.get(l));kept+=ls.size();count++;
 List<?> vs=(List<?>)call(sb,"lookupVerticalSections"),hs=(List<?>)call(sb,"lookupHorizontalSections");
 String selectedV=sections(vs),selectedH=sections(hs),selectedVI=ids(vs),selectedHI=ids(hs);
 String raw=rawSticks(sys,vs,hs,(Integer)get(p,"maxStemThickness"),0);List<?>chunks=(List<?>)call(sb,"lookupChunks",parts);
 List<?>finals=(List<?>)get(sb,"items");String builder="{\"items\":"+finalItems(finals)+",\"prefix_lengths\":"+prefixLengths(sb,finals.size())+",\"length_map\":"+intMap((Map<?,?>)get(sb,"lengthMap"))+",\"profile\":"+call(call(sheet,"getStub"),"getProfile")+",\"gap_map\":"+intMap((Map<?,?>)call(retr,"getGapMap"))+"}";
 String lookup="{\"selected_vertical_sections\":"+selectedV+",\"selected_horizontal_sections\":"+selectedH+",\"selected_vertical_ids\":"+selectedVI+",\"selected_horizontal_ids\":"+selectedHI+",\"raw_glyphs\":"+raw+",\"retained_chunks\":"+glyphs(chunks)+",\"head_glyph\":"+physical(call(h,"getGlyph"))+",\"head_vip\":"+call(h,"isVip")+",\"max_stem_thickness\":"+get(p,"maxStemThickness")+",\"max_line_section_dx\":"+get(p,"maxLineSectionDx")+"}";

 cs.add("{\"head_bounds\":"+rect(call(h,"getBounds"))+",\"shape\":\""+call(h,"getShape")+"\",\"side\":\""+side+"\",\"vertical\":\""+vert+"\",\"reference\":"+point(call(c,"getReferencePoint"))+",\"theoretical_line\":"+line(get(sb,"theoLine"))+",\"builder_y_range\":"+rect(get(sb,"yRange"))+",\"start_stump\":"+(stump==null?"null":physical(stump))+",\"initial_seeds\":"+input+",\"selected_linkers\":["+String.join(",",lr)+"],\"retained_seeds\":"+glyphs(parts)+",\"retained_linker_indices\":"+indices+",\"last_head_y\":"+get(sb,"lastHeadY")+",\"pre_chunk_items\":"+items(filtered,ids)+",\"chunk_lookup\":"+lookup+",\"builder_items\":"+builder+"}");
 }}ss.add("{\"system\":"+call(sys,"getId")+",\"cases\":["+String.join(",",cs)+"]}");}
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"original_phase\":\"XML_loaded_inspection_replay_before_linking_and_epilog\",\"head_corners\":"+count+",\"initial_seed_occurrences\":"+seedsCount+",\"initial_linker_occurrences\":"+total+",\"retained_linker_occurrences\":"+kept+",\"systems\":["+String.join(",",ss)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
